/*
 * A015901  Inverse of 1892nd cyclotomic polynomial.
 * https://oeis.org/A015901
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  sign, easy
 * Formula:   not stated
 * Range:     i8 n <= 2000, i16 n <= 2000, i32 n <= 2000, i64 n <= 2000,
 *            i128 n <= 2000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence generated by the coefficients of the formal power
   series 1 / Φ_1892(x), i.e.  a(0) = 1 and for n>0

      a(n) = -∑_{i=1}^{min(n,840)} φ_i * a(n-i)

   where φ_i are the coefficients of the cyclotomic polynomial
   Φ_1892(x).  The sequence is periodic with period 1892. */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* External integer types supplied by the build. */
extern seq_t a(idx_t n);

/*-------------------------------------*/
/* Period length of the sequence */
#define PERIOD 1892

/* Polynomial degree bounds */
#define MAX_DEG 2004   /* >= max(∑k for μ=1, ∑k for μ=-1) */

/* Storage for sequence values and for intermediate polynomials */
static seq_t a_values[PERIOD];
static bool init_done = false;

static seq_t polyP[MAX_DEG + 1];
static seq_t polyQ[MAX_DEG + 1];
static seq_t temp_poly[MAX_DEG + 1];
static seq_t phi[MAX_DEG + 1];   /* will hold Φ_1892 coefficients */

/* Multiply a polynomial by (x^k - 1) in place.
   Parameters:
       poly  - array of coefficients, degree = *deg
       deg   - pointer to current degree (modified)
       k     - exponent of x in factor
*/
static void mult_xk_minus1(seq_t *poly, int *deg, int k)
{
    int old_deg = *deg;
    int new_deg = old_deg + k;
    /* Zero temp array up to new_deg */
    for (int i = 0; i <= new_deg; ++i)
        temp_poly[i] = 0;

    /* (x^k - 1) * poly */
    for (int i = 0; i <= old_deg; ++i) {
        temp_poly[i]     -= poly[i];       /* -1 term   */
        temp_poly[i + k] += poly[i];       /* x^k term  */
    }

    /* copy back and update degree */
    for (int i = 0; i <= new_deg; ++i)
        poly[i] = temp_poly[i];
    *deg = new_deg;
}

/* Monic polynomial long division: divide N by D (monic of degree degD).
   N degN is updated to the remainder degree (should become < degD)
   Quotient Q of size at least (degN - degD + 1) is written.
   All arrays are of type seq_t.
*/
static void poly_div_monic(seq_t *N, int *degN, const seq_t *D, int degD, seq_t *Q)
{
    /* Work from higher degree downward */
    while (*degN >= degD) {
        seq_t coeff = N[*degN];
        Q[*degN - degD] = coeff;
        if (coeff != 0) {
            for (int j = 0; j <= degD; ++j)
                N[*degN - j] -= coeff * D[degD - j];
        }
        (*degN)--;
    }
    /* remainder N up to new degree *degN is zero (ignored) */
}

/* Initialise the period table once. */
static void init_sequence(void)
{
    /* 1. Build numerator P and denominator Q for Φ_1892(x) */
    int degP = 0, degQ = 0;
    polyP[0] = 1;
    polyQ[0] = 1;
    for (int i = 1; i <= MAX_DEG; ++i) {
        polyP[i] = 0;
        polyQ[i] = 0;
    }

    /* μ = +1 factors (x^{n/d} - 1) */
    mult_xk_minus1(polyP, &degP, 1892);  /* d=1  -> k=1892  */
    mult_xk_minus1(polyP, &degP,   86);  /* d=22 -> k=86    */
    mult_xk_minus1(polyP, &degP,   22);  /* d=86 -> k=22    */
    mult_xk_minus1(polyP, &degP,    4);  /* d=473-> k=4     */

    /* μ = -1 factors (into Q) */
    mult_xk_minus1(polyQ, &degQ,  946);  /* d=2  -> k=946  */
    mult_xk_minus1(polyQ, &degQ,  172);  /* d=11 -> k=172  */
    mult_xk_minus1(polyQ, &degQ,   44);  /* d=43 -> k=44   */
    mult_xk_minus1(polyQ, &degQ,    2);  /* d=946-> k=2    */

    /* 2. Divide P by Q to obtain Φ_1892(x) */
    int degPhi = degP - degQ;  /* should be 840 */
    for (int i = 0; i <= degPhi; ++i)
        phi[i] = 0;
    poly_div_monic(polyP, &degP, polyQ, degQ, phi);
    /* after division, polyP contains the remainder (zero), degP may be < degQ */

    /* 3. Compute a(n) for 0 <= n < PERIOD using recurrence */
    a_values[0] = 1;  /* a(0) = 1 */
    for (int n = 1; n < PERIOD; ++n) {
        seq_t sum = 0;
        int upper = (n < degPhi) ? n : degPhi;
        for (int i = 1; i <= upper; ++i) {
            sum += phi[i] * a_values[n - i];
        }
        a_values[n] = -sum;
    }
    init_done = true;
}

/* Public function ----------------------------------------------------- */
seq_t a(idx_t n)
{
    if (!init_done)
        init_sequence();

    idx_t m = n % PERIOD;  /* periodicity */
    return a_values[(int)m];
}
